package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import java.util.*;
public final class DwfRenderer implements BlockEntityRenderer<DwfBlockEntity>{
 private static final class View{DwfModel model;DwfModel.PoseBuffer poses;org.joml.Matrix4f[]matrices;float seconds=Float.NaN,left,right;double motionTick=Double.NaN,animationTime;final DwfVisualState.Lid input=new DwfVisualState.Lid(),output=new DwfVisualState.Lid();net.minecraft.world.item.ItemStack product=net.minecraft.world.item.ItemStack.EMPTY;DwfProductPreview.Preview preview;}
 private final Map<DwfBlockEntity,View>views=new WeakHashMap<>();public DwfRenderer(BlockEntityRendererProvider.Context ctx){}
 @Override public int getViewDistance(){return 96;}
 @Override public void render(DwfBlockEntity b,float partial,PoseStack p,MultiBufferSource buffers,int light,int overlay){if(!b.controller()||b.getLevel()==null)return;double distance=Minecraft.getInstance().gameRenderer.getMainCamera().getPosition().distanceToSqr(b.getBlockPos().getCenter());if(distance>96*96)return;var view=views.computeIfAbsent(b,k->new View());boolean gad=DwfProductPreview.gad(b.product);var model=gad?DwfModel.gad():DwfModel.get();if(view.model!=model){view.model=model;view.poses=model.poseBuffer();view.seconds=Float.NaN;}double now=b.getLevel().getGameTime()+partial;view.input.viewers(b.inputViewers,now);view.output.viewers(b.outputViewers,now);boolean active=b.visualStatus.equals("RUNNING");double progress=Math.max(0,Math.min(b.required,b.progress+(active?Math.max(0,now-b.visualTick):0)));// Authored 12-second motion loops in six seconds, independently of recipe duration.
if(Double.isNaN(view.motionTick))view.motionTick=now;if(active)view.animationTime+=Math.max(0,Math.min(2,now-view.motionTick))*.1;view.motionTick=now;float seconds=(float)(view.animationTime%12);if(distance>48*48)seconds=0;float left=(float)view.input.value(now),right=(float)view.output.value(now);if(distance<=48*48&&(view.seconds!=seconds||view.left!=left||view.right!=right)){view.matrices=model.poses(view.poses,seconds,left,right);view.seconds=seconds;view.left=left;view.right=right;}var matrices=distance>48*48||seconds==0&&left==0&&right==0?model.restPose():view.matrices;p.pushPose();p.translate(.5,0,.5);p.mulPose(Axis.YP.rotationDegrees(-b.facing().toYRot()));model.draw(p,buffers,light,overlay,matrices,false);
  if(!gad&&distance<48*48&&!b.product.isEmpty()&&progress>0){if(!net.minecraft.world.item.ItemStack.isSameItemSameTags(view.product,b.product)){view.product=b.product.copy();view.preview=DwfProductPreview.resolve(b.product);}p.pushPose();model.workpiece(p,matrices);double fraction=progress/Math.max(1,b.required);p.translate(DwfVisualState.transferX(fraction),0,0);view.preview.phase((float)fraction);view.preview.draw(p,buffers,light,overlay);p.popPose();}DwfVisualState.Status status;try{status=b.visualStatus.equals("RUNNING")?DwfVisualState.Status.ACTIVE:DwfVisualState.Status.valueOf(b.visualStatus);}catch(IllegalArgumentException ex){status=DwfVisualState.Status.ERROR;}model.lamp(p,buffers,matrices,DwfVisualState.lamp(status,now),overlay);model.draw(p,buffers,light,overlay,matrices,true);p.popPose();}
}
